export const ResultsDisplay: React.FC<ResultsDisplayProps> = ({ 
  files, 
  totals, 
  onRemoveFile, 
  onClearAll, 
  onReorderFiles, 
  singleSidedCost, 
  doubleSidedCost, 
  onCostChange, 
  onOpenRenameModal,
  viewMode,
  onViewModeChange,
  separateOrientations,
  onOrientationSeparatorToggle,
  isZipping,
  onDownloadZip,
  unitLabel,
  showOrientationInfo
}) => {
  const dragItemIndex = useRef<number | null>(null);
  const dragOverItemIndex = useRef<number | null>(null);

  const handleDragStart = (e: React.DragEvent<HTMLElement>, index: number) => {
    dragItemIndex.current = index;
    e.dataTransfer.effectAllowed = 'move';
    setTimeout(() => {
      e.currentTarget.classList.add('opacity-40');
    }, 0);
  };

  const handleDragEnter = (e: React.DragEvent<HTMLElement>, index: number) => {
    if (dragItemIndex.current === index) return;
    dragOverItemIndex.current = index;
    e.currentTarget.classList.add('bg-white/5');
  };

  const handleDragLeave = (e: React.DragEvent<HTMLElement>) => {
    e.currentTarget.classList.remove('bg-white/5');
  };

  const handleDrop = (e: React.DragEvent<HTMLElement>) => {
    e.currentTarget.classList.remove('bg-white/5');
    if (dragItemIndex.current !== null && dragOverItemIndex.current !== null) {
      onReorderFiles(dragItemIndex.current, dragOverItemIndex.current);
    }
  };

  const handleDragEnd = (e: React.DragEvent<HTMLElement>) => {
    e.currentTarget.classList.remove('opacity-40');
    dragItemIndex.current = null;
    dragOverItemIndex.current = null;
  };

  if (files.length === 0) {
    return (
       <div className="mt-8 space-y-8">
          <CostCalculator 
            singleSidedCost={singleSidedCost}
            doubleSidedCost={doubleSidedCost}
            onCostChange={onCostChange}
            separateOrientations={separateOrientations}
            onOrientationSeparatorToggle={onOrientationSeparatorToggle}
            unitLabel={unitLabel}
            showOrientationToggle={showOrientationInfo}
          />
       </div>
    )
  }

  const ViewToggleButton: React.FC<{mode: ViewMode, icon: React.ReactNode}> = ({mode, icon}) => (
    <button
      onClick={() => onViewModeChange(mode)}
      className={`p-2.5 rounded-xl transition-all ${viewMode === mode ? 'bg-emerald-600 text-white shadow-lg shadow-emerald-900/40' : 'bg-white/5 text-slate-400 hover:bg-white/10 hover:text-white'}`}
      aria-label={`Switch to ${mode} view`}
    >
      {icon}
    </button>
  );

  return (
    <div className="mt-8 space-y-12">
      <CostCalculator 
        singleSidedCost={singleSidedCost}
        doubleSidedCost={doubleSidedCost}
        onCostChange={onCostChange}
        separateOrientations={separateOrientations}
        onOrientationSeparatorToggle={onOrientationSeparatorToggle}
        unitLabel={unitLabel}
        showOrientationToggle={showOrientationInfo}
      />

      <section>
        <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 mb-6">
          <div className="flex items-center gap-3">
            <div className="w-1 h-8 bg-emerald-500 rounded-full"></div>
            <h2 className="text-2xl font-black text-white tracking-tight">Executive Summary</h2>
          </div>
          <div className="flex items-center gap-3 flex-wrap">
            <button
              onClick={onDownloadZip}
              disabled={isZipping}
              className="px-6 py-2.5 bg-emerald-600/20 text-emerald-400 text-sm font-black rounded-xl border border-emerald-500/30 hover:bg-emerald-600 hover:text-white transition-all disabled:bg-slate-900/40 disabled:text-slate-500 disabled:border-white/5 flex items-center gap-2"
            >
              {isZipping ? <SpinnerIcon className="w-5 h-5 animate-spin"/> : <ZipIcon className="w-5 h-5"/>}
              <span>{isZipping ? 'Zipping...' : 'Export Intel'}</span>
            </button>
            <button
              onClick={onOpenRenameModal}
              className="px-6 py-2.5 bg-white/5 text-white text-sm font-black rounded-xl border border-white/10 hover:bg-white/10 transition-all"
            >
              Rename Sequence
            </button>
            <button
              onClick={onClearAll}
              className="px-6 py-2.5 bg-red-600/10 text-red-400 text-sm font-black rounded-xl border border-red-500/30 hover:bg-red-600 hover:text-white transition-all"
            >
              Purge Database
            </button>
          </div>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
          <SummaryCard icon={<DocumentIcon className="w-6 h-6 text-white"/>} title="Units Counted" value={files.length} color="bg-blue-600"/>
          <SummaryCard icon={<DocumentIcon className="w-6 h-6 text-white"/>} title={`Total ${unitLabel}s`} value={totals.totalCount} color="bg-emerald-600"/>
          <SummaryCard icon={<SheetIcon className="w-6 h-6 text-white"/>} title="1-Sided Total" value={totals.totalSingleSidedPrice} suffix="₹" color="bg-orange-600"/>
          <SummaryCard icon={<SheetIcon className="w-6 h-6 text-white"/>} title="2-Sided Total" value={totals.totalDoubleSidedPrice} suffix="₹" color="bg-purple-600"/>
        </div>

        {showOrientationInfo && (
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-6 mt-6">
            <SummaryCard icon={<PortraitIcon className="w-6 h-6 text-white"/>} title="Portrait Frequency" value={totals.totalPortraitCount} color="bg-teal-600"/>
            <SummaryCard icon={<LandscapeIcon className="w-6 h-6 text-white"/>} title="Landscape Frequency" value={totals.totalLandscapeCount} color="bg-indigo-600"/>
          </div>
        )}
      </section>

      <section>
        <div className="flex justify-between items-center mb-6">
          <div className="flex items-center gap-3">
            <div className="w-1 h-8 bg-emerald-500 rounded-full"></div>
            <h2 className="text-2xl font-black text-white tracking-tight">Intelligence Feed</h2>
          </div>
          <div className="bg-slate-950/40 p-1.5 rounded-2xl border border-white/10 flex gap-2">
            <ViewToggleButton mode="list" icon={<ListViewIcon className="w-5 h-5"/>} />
            <ViewToggleButton mode="card" icon={<CardViewIcon className="w-5 h-5"/>} />
          </div>
        </div>

        {viewMode === 'list' && (
          <div className="bg-slate-900/60 backdrop-blur-xl rounded-3xl border border-white/5 overflow-hidden shadow-2xl">
            <ul className="divide-y divide-white/5">
              {files.map((file, index) => (
                <li 
                  key={file.id} 
                  className="p-6 group transition-all"
                  draggable
                  onDragStart={(e) => handleDragStart(e, index)}
                  onDragEnter={(e) => handleDragEnter(e, index)}
                  onDragLeave={handleDragLeave}
                  onDrop={handleDrop}
                  onDragEnd={handleDragEnd}
                  onDragOver={(e) => e.preventDefault()}
                >
                  <div className="flex justify-between items-start">
                      <div className="flex items-center gap-5 flex-1 pr-4">
                          <div className="cursor-grab active:cursor-grabbing p-2 bg-white/5 rounded-lg group-hover:bg-emerald-500/20 transition-colors" title="Reorder Record">
                              <DragHandleIcon className="w-5 h-5 text-slate-500 group-hover:text-emerald-400 transition-colors" />
                          </div>
                          <div className="flex-1">
                              <p className="font-bold text-white text-lg break-all group-hover:text-emerald-300 transition-colors">{file.name}</p>
                          </div>
                      </div>
                      <button
                        onClick={() => onRemoveFile(file.id)}
                        className="p-3 -mr-2 -mt-2 flex-shrink-0 rounded-xl text-slate-500 hover:bg-red-500/20 hover:text-red-400 transition-all"
                        aria-label={`Remove ${file.name}`}
                      >
                        <CloseIcon className="w-5 h-5" />
                      </button>
                  </div>
                  <div className="mt-4 pl-12 flex flex-wrap gap-x-8 gap-y-3">
                      <div className="flex items-center gap-2 text-sm">
                          <span className="text-slate-500 font-black uppercase tracking-widest text-[10px]">{unitLabel}s</span>
