export const ZipIcon: React.FC<IconProps> = (props) => (
  <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" {...props}>
    <path strokeLinecap="round" strokeLinejoin="round" d="M20.25 7.5l-.625 10.632a2.25 2.25 0 01-2.247 2.118H6.622a2.25 2.25 0 01-2.247-2.118L3.75 7.5M10 11.25h4M3.375 7.5h17.25c.621 0 1.125-.504 1.125-1.125v-1.5c0-.621-.504-1.125-1.125-1.125H3.375c-.621 0-1.125.504-1.125 1.125v1.5c0 .621.504 1.125 1.125 1.125z" />
  </svg>
);

import React, { useState, useCallback, useMemo, useEffect } from 'react';
import { FileUploader } from './components/FileUploader';
import { ResultsDisplay } from './components/ResultsDisplay';
import { countPdfPages, type PageCounts } from './services/pdfService';
import { countPptxSlides, countExcelSheets, countDocxPages, type OfficeCounts } from './services/officeService';
import { type DocFileData, type ViewMode, type FileType } from './types';
import { LogoIcon, NewTabIcon } from './components/Icons';
import { RenameModal } from './components/RenameModal';

declare const JSZip: any;
declare const saveAs: any;

function App() {
  const [activeTab, setActiveTab] = useState<FileType>('pdf');

  const [pdfFiles, setPdfFiles] = useState<DocFileData[]>([]);
  const [pptxFiles, setPptxFiles] = useState<DocFileData[]>([]);
  const [excelFiles, setExcelFiles] = useState<DocFileData[]>([]);
  const [docxFiles, setDocxFiles] = useState<DocFileData[]>([]);
  const [imageFiles, setImageFiles] = useState<DocFileData[]>([]);

  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [isZipping, setIsZipping] = useState<boolean>(false);
  const [errors, setErrors] = useState<string[]>([]);

  const [singleSidedCost, setSingleSidedCost] = useState<number>(10);
  const [doubleSidedCost, setDoubleSidedCost] = useState<number>(10);

  const [isRenameModalOpen, setIsRenameModalOpen] = useState(false);
  const [viewMode, setViewMode] = useState<ViewMode>('list');
  const [separateOrientations, setSeparateOrientations] = useState<boolean>(false);

  const getCurrentFiles = useCallback(() => {
    switch (activeTab) {
      case 'pdf': return pdfFiles;
      case 'pptx': return pptxFiles;
      case 'xlsx': return excelFiles;
      case 'docx': return docxFiles;
      case 'image': return imageFiles;
    }
  }, [activeTab, pdfFiles, pptxFiles, excelFiles, docxFiles, imageFiles]);

  const setCurrentFiles = useCallback((updater: (files: DocFileData[]) => DocFileData[]) => {
    switch (activeTab) {
      case 'pdf': setPdfFiles(updater); break;
      case 'pptx': setPptxFiles(updater); break;
      case 'xlsx': setExcelFiles(updater); break;
      case 'docx': setDocxFiles(updater); break;
      case 'image': setImageFiles(updater); break;
    }
  }, [activeTab]);

  const calculateSheetCount = useCallback((count: number, portraitCount: number, landscapeCount: number, separate: boolean): number => {
    if (separate && portraitCount + landscapeCount > 0) {
      return Math.ceil(portraitCount / 2) + Math.ceil(landscapeCount / 2);
    }
    return Math.ceil(count / 2);
  }, []);

  const handleFilesSelected = useCallback(async (files: FileList) => {
    if (files.length === 0) return;

    setIsLoading(true);
    setErrors([]);
    const newFilesData: DocFileData[] = [];
    const newErrors: string[] = [];

    for (const file of Array.from(files)) {
      try {
        let count = 0;
        let portrait = 0;
        let landscape = 0;

        if (activeTab === 'pdf') {
            if (file.type !== 'application/pdf') {
                newErrors.push(`File "${file.name}" is not a PDF.`);
                continue;
            }
            const counts: PageCounts = await countPdfPages(file);
            count = counts.total;
            portrait = counts.portrait;
            landscape = counts.landscape;
        } else if (activeTab === 'pptx') {
            if (!file.name.endsWith('.pptx')) {
                newErrors.push(`File "${file.name}" is not a PowerPoint (.pptx) file.`);
                continue;
            }
            const counts: OfficeCounts = await countPptxSlides(file);
            count = counts.total;
            landscape = count; 
        } else if (activeTab === 'xlsx') {
            if (!file.name.endsWith('.xlsx')) {
                newErrors.push(`File "${file.name}" is not an Excel (.xlsx) file.`);
                continue;
            }
            const counts: OfficeCounts = await countExcelSheets(file);
            count = counts.total;
            portrait = count; 
        } else if (activeTab === 'docx') {
            if (!file.name.endsWith('.docx')) {
                newErrors.push(`File "${file.name}" is not a Word (.docx) file.`);
                continue;
            }
            const counts: OfficeCounts = await countDocxPages(file);
            count = counts.total;
            portrait = count;
        } else if (activeTab === 'image') {
            if (!file.type.startsWith('image/')) {
                newErrors.push(`File "${file.name}" is not an image.`);
                continue;
            }
            // Images are counted as 1 page each by default
            count = 1;
            portrait = 1; 
        }

        const sheetCount = calculateSheetCount(count, portrait, landscape, activeTab === 'pdf' ? separateOrientations : false);

        newFilesData.push({
          id: `${file.name}-${file.lastModified}-${Math.random()}`,
          name: file.name,
          file: file,
          type: activeTab,
          count: count,
          portraitCount: portrait,
          landscapeCount: landscape,
          sheetCount: sheetCount,
          singleSidedPrice: count * singleSidedCost,
          doubleSidedPrice: sheetCount * doubleSidedCost,
        });
      } catch (err: any) {
        newErrors.push(`Error with "${file.name}": ${err.message}`);
      }
    }

    setCurrentFiles(prevFiles => [...prevFiles, ...newFilesData]);
    setErrors(newErrors);
    setIsLoading(false);
  }, [activeTab, singleSidedCost, doubleSidedCost, separateOrientations, calculateSheetCount, setCurrentFiles]);

  const handleCostChange = useCallback((type: 'single' | 'double', value: number) => {
    const newCost = isNaN(value) || value < 0 ? 0 : value;

    if (type === 'single') {
      setSingleSidedCost(newCost);
      setCurrentFiles(prevFiles => 
        prevFiles.map(file => ({
          ...file,
          singleSidedPrice: file.count * newCost,
        }))
      );
    } else {
      setDoubleSidedCost(newCost);
      setCurrentFiles(prevFiles => 
        prevFiles.map(file => ({
          ...file,
          doubleSidedPrice: file.sheetCount * newCost,
        }))
      );
    }
  }, [setCurrentFiles]);

  const handleOrientationSeparatorToggle = useCallback((enabled: boolean) => {
    setSeparateOrientations(enabled);
    if (activeTab === 'pdf') {
        setPdfFiles(prevFiles => 
          prevFiles.map(file => {
            const newSheetCount = calculateSheetCount(file.count, file.portraitCount, file.landscapeCount, enabled);
            return {
              ...file,
              sheetCount: newSheetCount,
              doubleSidedPrice: newSheetCount * doubleSidedCost,
            };
          })
        );
    }
  }, [calculateSheetCount, doubleSidedCost, activeTab]);

  const handleRemoveFile = useCallback((id: string) => {
    setCurrentFiles(prevFiles => prevFiles.filter(file => file.id !== id));
  }, [setCurrentFiles]);

  const handleClearAll = useCallback(() => {
    setCurrentFiles(() => []);
    setErrors([]);
  }, [setCurrentFiles]);

  const handleOpenInNewTab = useCallback(() => {
    window.open(window.location.href, '_blank', 'noopener,noreferrer');
  }, []);

  const handleReorderFiles = useCallback((startIndex: number, endIndex: number) => {
    setCurrentFiles(prevFiles => {
      const newFiles = [...prevFiles];
      const [removed] = newFiles.splice(startIndex, 1);
      newFiles.splice(endIndex, 0, removed);
      return newFiles;
    });
  }, [setCurrentFiles]);

  const handleBatchRename = useCallback((prefix: string, suffix: string) => {
    setCurrentFiles(prevFiles =>
      prevFiles.map(file => {
        const lastDotIndex = file.name.lastIndexOf('.');
        if (lastDotIndex === -1) { 
          return { ...file, name: `${prefix}${file.name}${suffix}` };
        }
        const baseName = file.name.substring(0, lastDotIndex);
        const extension = file.name.substring(lastDotIndex); 
        return { ...file, name: `${prefix}${baseName}${suffix}${extension}` };
      })
    );
    setIsRenameModalOpen(false);
  }, [setCurrentFiles]);

  const handleDownloadZip = useCallback(async () => {
    const currentFiles = getCurrentFiles();
    if (!currentFiles.length || isZipping) return;

    setIsZipping(true);
    setErrors([]);

    try {
      const zip = new JSZip();
      const useFolders = activeTab === 'pdf';
      const portraitFolder = useFolders ? zip.folder("portrait") : null;
      const landscapeFolder = useFolders ? zip.folder("landscape") : null;
      const mainFolder = zip;

      const usedNamesPortrait = new Set<string>();
      const usedNamesLandscape = new Set<string>();
      const usedNamesMain = new Set<string>();

      for (const file of currentFiles) {
        const fileData = file.file; 
        const originalName = file.name;

        let targetFolder: any = mainFolder;
        let usedNames = usedNamesMain;

        if (useFolders) {
            const isPortrait = file.portraitCount >= file.landscapeCount;
            usedNames = isPortrait ? usedNamesPortrait : usedNamesLandscape;
            targetFolder = isPortrait ? portraitFolder : landscapeFolder;
        }

        const lastDotIndex = originalName.lastIndexOf('.');
        const baseName = lastDotIndex === -1 ? originalName : originalName.substring(0, lastDotIndex);
        const extension = lastDotIndex === -1 ? '' : originalName.substring(lastDotIndex);

        let finalName = originalName;
        let counter = 1;

        while (usedNames.has(finalName)) {
          finalName = `${baseName} (${counter})${extension}`;
          counter++;
        }

        usedNames.add(finalName);
        targetFolder.file(finalName, fileData);
      }

      const zipBlob = await zip.generateAsync({ type: "blob" });
      saveAs(zipBlob, `raj_expo_${activeTab}_documents.zip`);

    } catch (err: any) {
      setErrors(prev => [...prev, `Failed to create ZIP file: ${err.message}`]);
    } finally {
      setIsZipping(false);
    }
  }, [getCurrentFiles, isZipping, activeTab]);

  useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      const target = event.target as HTMLElement;
      if (target.tagName === 'INPUT' || target.tagName === 'TEXTAREA' || target.isContentEditable) return;
      if (isRenameModalOpen) return;

      switch (event.key.toLowerCase()) {
        case 'c': handleClearAll(); break;
        case 'r': if (getCurrentFiles().length > 0) setIsRenameModalOpen(true); break;
        case 'l': setViewMode('list'); break;
        case 'k': setViewMode('card'); break;
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [handleClearAll, isRenameModalOpen, getCurrentFiles]);

  const totals = useMemo(() => {
    return getCurrentFiles().reduce(
      (acc, file) => {
        acc.totalCount += file.count;
        acc.totalPortraitCount += file.portraitCount;
        acc.totalLandscapeCount += file.landscapeCount;
        acc.totalSheets += file.sheetCount; 
        acc.totalSingleSidedPrice += file.singleSidedPrice;
        acc.totalDoubleSidedPrice += file.doubleSidedPrice;
        return acc;
      },
      { totalCount: 0, totalSheets: 0, totalSingleSidedPrice: 0, totalDoubleSidedPrice: 0, totalPortraitCount: 0, totalLandscapeCount: 0 }
    );
  }, [getCurrentFiles]);

  const activeFiles = getCurrentFiles();
  const getAcceptLabel = () => {
    switch(activeTab) {
        case 'pdf': return '.pdf';
        case 'pptx': return '.pptx';
        case 'xlsx': return '.xlsx';
        case 'docx': return '.docx';
        case 'image': return 'image/*,.jpg,.jpeg,.png,.webp,.gif,.bmp,.tiff';
    }
  };
  const getUnitLabel = () => {
    switch(activeTab) {
        case 'pdf': return 'Page';
        case 'pptx': return 'Slide';
        case 'xlsx': return 'Sheet';
        case 'docx': return 'Page';
        case 'image': return 'Image';
    }
  };
  const getTabLabel = () => {
    switch(activeTab) {
        case 'pdf': return 'PDF';
        case 'pptx': return 'PowerPoint';
        case 'xlsx': return 'Excel';
        case 'docx': return 'Word';
        case 'image': return 'Images';
    }
  };

  return (
    <div className="min-h-screen font-sans p-4 sm:p-6 lg:p-8">
      <div className="max-w-6xl mx-auto relative">
        <button
          onClick={handleOpenInNewTab}
          className="absolute top-0 right-0 hidden sm:flex items-center gap-2 px-4 py-2 text-sm font-bold text-emerald-400 bg-slate-900/60 backdrop-blur-md border border-white/10 rounded-xl hover:bg-slate-800/80 hover:scale-105 transition-all focus:outline-none focus:ring-2 focus:ring-emerald-500"
          aria-label="Open in new tab"
        >
          <NewTabIcon className="w-5 h-5" />
          <span>Pop-up View</span>
        </button>

        <header className="text-center mb-10 pt-4 sm:pt-0">
          <div className="flex items-center justify-center gap-5 mb-3">
            <div className="bg-emerald-600/20 p-3 rounded-2xl border border-emerald-500/30 backdrop-blur-sm">
                <LogoIcon className="w-14 h-14 text-emerald-400" />
            </div>
            <h1 className="text-5xl sm:text-6xl font-black text-white tracking-tighter drop-shadow-2xl">
              RAJ <span className="text-emerald-500">EXPO</span>
            </h1>
          </div>
          <p className="text-xl text-slate-400 font-medium tracking-wide opacity-80">
            Professional Multi-Format Document Analytics
          </p>
        </header>

        <div className="flex justify-center mb-10 overflow-x-auto pb-2">
            <div className="bg-slate-950/40 backdrop-blur-md p-1.5 rounded-2xl border border-white/10 flex space-x-2 shadow-2xl min-w-max">
                <button onClick={() => setActiveTab('pdf')} className={`px-6 py-2.5 rounded-xl text-sm font-bold transition-all duration-300 ${activeTab === 'pdf' ? 'bg-emerald-600 text-white shadow-[0_0_20px_rgba(16,185,129,0.3)]' : 'text-slate-400 hover:text-white hover:bg-white/5'}`}>PDF</button>
                <button onClick={() => setActiveTab('docx')} className={`px-6 py-2.5 rounded-xl text-sm font-bold transition-all duration-300 ${activeTab === 'docx' ? 'bg-blue-600 text-white shadow-[0_0_20px_rgba(37,99,235,0.3)]' : 'text-slate-400 hover:text-white hover:bg-white/5'}`}>Word</button>
                <button onClick={() => setActiveTab('pptx')} className={`px-6 py-2.5 rounded-xl text-sm font-bold transition-all duration-300 ${activeTab === 'pptx' ? 'bg-orange-600 text-white shadow-[0_0_20px_rgba(234,88,12,0.3)]' : 'text-slate-400 hover:text-white hover:bg-white/5'}`}>PowerPoint</button>
                <button onClick={() => setActiveTab('xlsx')} className={`px-6 py-2.5 rounded-xl text-sm font-bold transition-all duration-300 ${activeTab === 'xlsx' ? 'bg-emerald-500 text-white shadow-[0_0_20px_rgba(16,185,129,0.3)]' : 'text-slate-400 hover:text-white hover:bg-white/5'}`}>Excel</button>
                <button onClick={() => setActiveTab('image')} className={`px-6 py-2.5 rounded-xl text-sm font-bold transition-all duration-300 ${activeTab === 'image' ? 'bg-purple-600 text-white shadow-[0_0_20px_rgba(147,51,234,0.3)]' : 'text-slate-400 hover:text-white hover:bg-white/5'}`}>Images</button>
            </div>
        </div>

        <main className="space-y-8">
          <FileUploader 
            onFilesSelected={handleFilesSelected} 
            isLoading={isLoading} 
            accept={getAcceptLabel()}
            label={getTabLabel()}
          />

          {errors.length > 0 && (
            <div className="bg-red-950/40 backdrop-blur-md p-5 rounded-2xl border border-red-500/30 animate-pulse">
              <p className="font-bold text-red-300 mb-2 uppercase tracking-widest text-xs">System Errors</p>
              <ul className="list-disc list-inside text-red-400 text-sm space-y-1">
                {errors.map((e, index) => <li key={index}>{e}</li>)}
              </ul>
            </div>
          )}

          <ResultsDisplay
            files={activeFiles}
            totals={totals}
            onRemoveFile={handleRemoveFile}
            onClearAll={handleClearAll}
            onReorderFiles={handleReorderFiles}
            singleSidedCost={singleSidedCost}
            doubleSidedCost={doubleSidedCost}
            onCostChange={handleCostChange}
            onOpenRenameModal={() => setIsRenameModalOpen(true)}
            viewMode={viewMode}
            onViewModeChange={setViewMode}
            separateOrientations={separateOrientations}
            onOrientationSeparatorToggle={handleOrientationSeparatorToggle}
            isZipping={isZipping}
            onDownloadZip={handleDownloadZip}
            unitLabel={getUnitLabel()}
            showOrientationInfo={activeTab === 'pdf'}
          />
        </main>

        {isRenameModalOpen && (
          <RenameModal 
            files={activeFiles}
            onClose={() => setIsRenameModalOpen(false)}
            onRename={handleBatchRename}
          />
        )}

        <footer className="text-center mt-20 text-slate-500 pb-10 border-t border-white/5 pt-10">
          <p className="font-mono text-xs uppercase tracking-[0.2em] opacity-50">Authorized Personnel Only | Raj Expo &copy; 2024</p>
        </footer>
      </div>
    </div>
  );
}

export default App;
